CREATE TABLE metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE repositories (registration_id TEXT PRIMARY KEY, identity TEXT NOT NULL UNIQUE, document TEXT NOT NULL);
CREATE TABLE task_specs (task_id TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), digest TEXT NOT NULL, document TEXT NOT NULL, PRIMARY KEY(task_id,revision));
CREATE TABLE runs (run_id TEXT PRIMARY KEY, task_id TEXT NOT NULL, task_revision INTEGER NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), state TEXT NOT NULL, document TEXT NOT NULL, FOREIGN KEY(task_id,task_revision) REFERENCES task_specs(task_id,revision));
CREATE TABLE operations (command TEXT NOT NULL, run_id TEXT NOT NULL, operation_key TEXT NOT NULL, request_digest TEXT NOT NULL, response TEXT NOT NULL, PRIMARY KEY(command,run_id,operation_key));
CREATE TABLE events (event_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(run_id), seq INTEGER NOT NULL CHECK(seq>0), run_revision INTEGER NOT NULL, producer TEXT, producer_event_id TEXT, document TEXT NOT NULL, UNIQUE(run_id,seq), UNIQUE(producer,producer_event_id));
CREATE TABLE attempts (attempt_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(run_id), ordinal INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), document TEXT NOT NULL, UNIQUE(run_id,ordinal));
CREATE UNIQUE INDEX one_active_attempt ON attempts(run_id) WHERE active=1;
CREATE TABLE leases (repository_id TEXT PRIMARY KEY REFERENCES repositories(registration_id), run_id TEXT NOT NULL REFERENCES runs(run_id), generation INTEGER NOT NULL CHECK(generation>0), token TEXT NOT NULL, state TEXT NOT NULL, document TEXT NOT NULL);
CREATE TABLE effects (effect_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(run_id), operation_key TEXT NOT NULL, kind TEXT NOT NULL, request_digest TEXT NOT NULL, phase TEXT NOT NULL, document TEXT NOT NULL, UNIQUE(run_id,kind,operation_key));
CREATE TABLE profiles (profile_id TEXT PRIMARY KEY, digest TEXT NOT NULL, document TEXT NOT NULL);
CREATE TABLE settings (name TEXT PRIMARY KEY, document TEXT NOT NULL);
CREATE TABLE evidence (evidence_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(run_id), document TEXT NOT NULL);
CREATE TABLE acceptances (acceptance_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(run_id), document TEXT NOT NULL);
CREATE TABLE authorities (authority_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(run_id), document TEXT NOT NULL);
CREATE TABLE blobs (sha256 TEXT PRIMARY KEY, bytes INTEGER NOT NULL CHECK(bytes>=0), media_type TEXT NOT NULL, redaction_version TEXT NOT NULL);
CREATE TRIGGER immutable_events_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'immutable events'); END;
CREATE TRIGGER immutable_events_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'immutable events'); END;
CREATE TRIGGER immutable_specs_update BEFORE UPDATE ON task_specs BEGIN SELECT RAISE(ABORT,'immutable specs'); END;
CREATE TRIGGER immutable_specs_delete BEFORE DELETE ON task_specs BEGIN SELECT RAISE(ABORT,'immutable specs'); END;
CREATE TRIGGER immutable_evidence_update BEFORE UPDATE ON evidence BEGIN SELECT RAISE(ABORT,'immutable evidence'); END;
CREATE TRIGGER immutable_evidence_delete BEFORE DELETE ON evidence BEGIN SELECT RAISE(ABORT,'immutable evidence'); END;
CREATE TRIGGER immutable_acceptances_update BEFORE UPDATE ON acceptances BEGIN SELECT RAISE(ABORT,'immutable acceptances'); END;
CREATE TRIGGER immutable_acceptances_delete BEFORE DELETE ON acceptances BEGIN SELECT RAISE(ABORT,'immutable acceptances'); END;
CREATE TRIGGER immutable_authorities_update BEFORE UPDATE ON authorities BEGIN SELECT RAISE(ABORT,'immutable authorities'); END;
CREATE TRIGGER immutable_authorities_delete BEFORE DELETE ON authorities BEGIN SELECT RAISE(ABORT,'immutable authorities'); END;
